export const CSS = "/* o palco da retrospectiva e do vídeo de divulgação — regras de\n * .historia-* e .promo-* do app.css do site (port fiel). */\n*{box-sizing:border-box;margin:0}\nhtml,body{height:100%;background:transparent;overflow:hidden;font-family:-apple-system,\"SF Pro Text\",\"Helvetica Neue\",\"Segoe UI\",Roboto,Arial,sans-serif;-webkit-tap-highlight-color:transparent}\nbutton{font:inherit}\n[hidden]{display:none!important}\n.ponto-rec{width:10px;height:10px;border-radius:50%;background:#ff453a;animation:pisca 1s ease-in-out infinite}\n@keyframes pisca{50%{opacity:.3}}\n.historia{--cor:#2a1bff;--curva:cubic-bezier(.25,.1,.25,1);position:fixed;inset:0;display:grid;place-items:center;background:var(--cor);transition:background-color .5s var(--curva),opacity .25s;opacity:0;touch-action:manipulation;-webkit-user-select:none;user-select:none}\n.historia.visivel{opacity:1}\n.historia-palco{position:relative;height:calc(100dvh - 40px);aspect-ratio:9/16;max-width:100vw;border-radius:24px;overflow:hidden;background:var(--cor);box-shadow:0 30px 90px rgba(0,0,0,.35);cursor:pointer}\n.historia-palco canvas{width:100%;height:100%;display:block;object-fit:contain}\n.historia-topo{position:absolute;left:0;right:0;top:0;padding:14px 14px 30px;pointer-events:none;background:linear-gradient(rgba(0,0,0,.28),rgba(0,0,0,0));opacity:0;transition:opacity .3s}\n.historia.comecou .historia-topo{opacity:1}\n.historia-barras{display:flex;gap:5px}\n.historia-barras span{flex:1;height:3.5px;border-radius:2px;background:rgba(255,255,255,.35);overflow:hidden}\n.historia-barras i{display:block;height:100%;background:#fff;transform-origin:left;transform:scaleX(0)}\n.historia-cab{display:flex;align-items:center;gap:6px;margin-top:10px;color:#fff;pointer-events:auto}\n.historia-marca{width:36px;height:36px;border-radius:9px;display:grid;place-items:center;flex:none;margin-right:6px;overflow:hidden}\n.historia-marca img{width:100%;height:100%;object-fit:contain}\n.historia-nome{display:grid;line-height:1.15;margin-right:auto;text-shadow:0 1px 4px rgba(0,0,0,.3)}\n.historia-nome b{font-size:14px}.historia-nome small{font-size:11px;opacity:.8}\n.historia-bt{width:40px;height:40px;border:0;border-radius:50%;background:transparent;color:#fff;cursor:pointer;display:grid;place-items:center;filter:drop-shadow(0 1px 3px rgba(0,0,0,.35))}\n.historia-bt:hover{background:rgba(255,255,255,.14)}\n.historia-bt[aria-pressed=\"true\"]{background:rgba(255,255,255,.22)}\n.historia-pausa{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:84px;height:84px;border-radius:50%;display:grid;place-items:center;color:#fff;background:rgba(0,0,0,.35);pointer-events:none;-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}\n.historia-gravando,.promo-gravando{position:absolute;left:14px;right:14px;bottom:16px;display:flex;align-items:center;justify-content:center;gap:8px;padding:10px 12px;border-radius:14px;color:#fff;font-size:13px;background:rgba(0,0,0,.5);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px)}\n.historia.gravando .historia-palco,.historia.gravando .historia-seta{pointer-events:none}\n.historia.gravando .historia-cab{opacity:.5}\n.historia-comecar{position:absolute;inset:0;border:0;cursor:pointer;color:#fff;display:grid;place-content:center;justify-items:center;gap:10px;text-align:center;padding:24px;background:rgba(20,10,90,.45);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}\n.historia-comecar b{font-size:26px;font-weight:800;letter-spacing:-.02em;max-width:280px;line-height:1.15}\n.historia-comecar small{font-size:14px;opacity:.85}\n.historia-comecar-ic{width:92px;height:92px;border-radius:50%;display:grid;place-items:center;padding-left:6px;background:#ffe14d;color:#2a1bff;box-shadow:0 16px 40px rgba(0,0,0,.3);margin-bottom:8px;animation:pulsa 1.8s ease-in-out infinite}\n@keyframes pulsa{50%{transform:scale(1.07)}}\n.historia-seta{position:absolute;top:50%;transform:translateY(-50%);width:56px;height:56px;border-radius:50%;border:0;display:grid;place-items:center;cursor:pointer;color:#fff;background:rgba(255,255,255,.16);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);transition:background .2s,transform .2s}\n.historia-seta:hover{background:rgba(255,255,255,.28);transform:translateY(-50%) scale(1.06)}\n.historia-seta.esq{left:max(24px,calc(50% - 50dvh * 9 / 16 - 96px))}\n.historia-seta.dir{right:max(24px,calc(50% - 50dvh * 9 / 16 - 96px))}\n@media (max-width:760px),(max-aspect-ratio:3/4){\n .historia-palco{height:100dvh;width:100vw;aspect-ratio:auto;border-radius:0;box-shadow:none}\n .historia-topo{padding-top:calc(var(--seguro-topo,0px) + 10px)}\n .historia-seta{display:none}\n}\n@media (prefers-reduced-motion:reduce){.historia-comecar-ic{animation:none}}\n.promo-palco{position:fixed;inset:0;display:grid;place-items:center;background:#050f2b}\n.promo-palco canvas{width:100%;height:100%;display:block;object-fit:contain}\n";
